    'about.missionP1': 'විශ්වවිද්‍යාල ප්‍රජාව තුළ ශිෂ්‍ය හැඳුනුම්පත්, යතුරු, පසුම්බි, ගණක යන්ත්‍ර, දුරකථන සහ සටහන් පොත් නිතර අස්ථානගත වේ. අතින් තබන ලේඛන සහ විසිරුණු සමාජ මාධ්‍ය පළ කිරීම් සෙවීම සහ තහවුරු කිරීම අපහසු කරයි.',
    'about.missionP2': 'Smart Lost & Found මඟින් නැතිවූ භාණ්ඩ වාර්තා කිරීම, හමුවූ භාණ්ඩ ලියාපදිංචි කිරීම සහ campus වාර්තා මත පදනම් වූ ශ්‍රේණිගත යෝජනා ලබාගැනීම සඳහා එකම තත්‍යකාලීන වේදිකාවක් සපයයි.',
    'about.matchingTitle': 'පැහැදිලි කළ හැකි ගැළපීම',
    'about.matchingDesc': 'සීමා කළ සමානතා ලකුණු කාණ්ඩය, පෙළ, ස්ථානය, දිනය, ටැග් සහ පෞද්ගලිකත්වයට ආරක්ෂිත රූප metadata සසඳයි. ලකුණක් හිමිකාරිත්වයට සාක්ෂියක් නොවේ.',
    'about.visionTitle': 'සමාලෝචනය කළ හැකි රූප සහාය',
    'about.visionDesc': 'අනුමත provider එකක් සකසා ඇති විට, රූප මඟින් සංවේදී නොවන ලේබල්, වර්ණ සහ භාණ්ඩ විස්තර යෝජනා කළ හැක. සෑම යෝජනාවක්ම පරිශීලකයා සමාලෝචනය කරන අතර අතින් ඇතුළත් කිරීම සැමවිටම ඇත.',
    'about.reclaimTitle': 'මානව තහවුරුකරණය සහිත ප්‍රතිසාධනය',
    'about.reclaimDesc': 'සම්බන්ධතා බෙදාගැනීමට හෝ භාරදීමට පෙර වාර්තාකරු සහ බලයලත් පරිපාලකයන් පෞද්ගලික සාක්ෂි සහ හිමිකාරිත්ව පිළිතුරු සමාලෝචනය කරයි.',
    'about.policyTitle': 'දත්ත සහ පද්ධති ප්‍රතිපත්ති',
    'about.policyIntro': 'ප්‍රතිසාධන ක්‍රියාවලිය පුරා පෞද්ගලිකත්ව, සාක්ෂි ප්‍රවේශ සහ රඳවාගැනීමේ පාලන යොදයි.',
    'about.publicPrivacyLabel': 'පොදු පෞද්ගලිකත්වය',
    'about.publicPrivacyDesc': 'වාර්තාකරු පොදු නාලිකාවක් තෝරාගන්නා තුරු හෝ බලයලත් claim ක්‍රියාවක් මඟින් නිකුත් කරන තුරු සම්බන්ධතා විස්තර සඟවා තබයි.',
    'about.privateEvidenceLabel': 'පෞද්ගලික සාක්ෂි',
    'about.privateEvidenceDesc': 'හිමිකාරිත්ව සාක්ෂි බලයලත් පාර්ශ්වයන්ට සහ පරිපාලකයන්ට පමණක් සීමා වන අතර media ප්‍රවේශය කාලසීමා සහිතය.',
    'about.retentionLabel': 'විසඳූ වාර්තා රඳවාගැනීම',
    'about.retentionDesc': 'විසඳූ වාර්තා පරිපාලක අනුමත රඳවාගැනීමේ කාලය අනුගමනය කරන අතර සකසා ඇති අවම ආරක්ෂිත කාලයට පෙර archive නොවේ.',
    'about.archiveNote': 'Archive කළ පොදු වාර්තාවලින් පොදු විස්තර සහ media ඉවත් කරයි. මෙහෙයුම් සහ audit වාර්තා ලේඛනගත රඳවාගැනීම සහ නිර්නාමිකරණ ක්‍රම අනුගමනය කරයි.',
