    'home.badge': 'විශ්වවිද්‍යාල Smart Lost & Found පද්ධතිය', 'home.title': 'SEUSL එකේ භාණ්ඩයක් නැති වුණාද?', 'home.titleAccent': 'බුද්ධිමත්ව නැවත ලබාගන්න.', 'home.subtitle': 'මිනිත්තු දෙකකට අඩුවෙන් වාර්තා කරන්න. සම්බන්ධතා තොරතුරු ආරක්ෂා කරමින් AI සහාය නැති හා හමු වාර්තා ගැළපීමට උපකාරී වේ.', 'home.reportLost': 'නැති වූ භාණ්ඩය වාර්තා කරන්න', 'home.reportFound': 'හමු වූ භාණ්ඩය වාර්තා කරන්න', 'home.searchReports': 'පවතින වාර්තා සොයන්න', 'home.completedRecoveries': 'සාර්ථකව ආපසු ලබාදුන්', 'home.activeAccounts': 'සක්‍රිය ගිණුම්', 'home.openMatches': 'විවෘත ගැළපීම්', 'home.featuresTitle': 'Smart L&F ආරක්ෂිතව ක්‍රියා කරන ආකාරය', 'home.featureMatching': 'පැහැදිලි කළ හැකි AI ගැළපීම', 'home.featureMatchingDesc': 'භාණ්ඩ විස්තර, ස්ථානය, කාලය සහ ආරක්ෂිත රූප සාක්ෂි සසඳයි. ලකුණු හිමිකාරිත්වයේ සාක්ෂියක් නොවේ.', 'home.featureRealtime': 'ක්ෂණික යාවත්කාලීන', 'home.featureRealtimeDesc': 'ගැළපීමක් හෝ හිමිකම් ඉල්ලීමක් වෙනස් වූ විට දැනුම්දීම් ලබාගන්න.', 'home.featureHuman': 'මානව තහවුරු කිරීම', 'home.featureHumanDesc': 'භාණ්ඩය භාරදීමට පෙර වාර්තාකරු සහ බලයලත් පරිපාලකයන් පෞද්ගලික සාක්ෂි පරීක්ෂා කරයි.', 'home.latestLost': 'මෑත නැති වූ වාර්තා', 'home.latestLostDesc': 'සිසුන් විසින් මෑතකදී වාර්තා කළ භාණ්ඩ', 'home.latestFound': 'මෑත හමු වූ භාණ්ඩ', 'home.latestFoundDesc': 'කැම්පස් තුළ හමු වී ආරක්ෂා කළ භාණ්ඩ', 'home.location': 'ස්ථානය', 'home.reported': 'වාර්තා කළේ', 'home.found': 'හමු වූයේ',
    'dashboard.welcome': 'නැවත සාදරයෙන් පිළිගනිමු, {name}', 'dashboard.heroTitle': 'භාණ්ඩ ආරක්ෂිතව නැවත ලබාගන්න', 'dashboard.heroDesc': 'පළමුව ගැළපීම් සහ හිමිකම් ඉල්ලීම් පරීක්ෂා කරන්න. AI යෝජනා කරයි; මිනිසුන් හිමිකාරිත්වය සහ භාරදීම තහවුරු කරයි.', 'dashboard.needsAttention': 'ඔබගේ අවධානය අවශ්‍යයි', 'dashboard.attentionDesc': 'භාණ්ඩයක් ආරක්ෂිතව නැවත ලබාදීමට උපකාරී වන ක්‍රියා.', 'dashboard.open': 'විවෘත {count}', 'dashboard.potentialMatches': 'විය හැකි ගැළපීම්', 'dashboard.reviewSuggestions': 'AI යෝජනා පරීක්ෂා කරන්න', 'dashboard.claimsToReview': 'පරීක්ෂා කළ යුතු හිමිකම්', 'dashboard.claimsToReviewDesc': 'කෙනෙකු ඔබගේ වාර්තාවට හිමිකම් කියයි', 'dashboard.pendingClaims': 'මගේ අපේක්ෂිත හිමිකම්', 'dashboard.pendingClaimsDesc': 'මානව තීරණයක් බලාපොරොත්තුවෙන්', 'dashboard.handoverPending': 'භාරදීම අපේක්ෂිතයි', 'dashboard.handoverDesc': 'භෞතිකව භාරදුන් පසු පමණක් තහවුරු කරන්න', 'dashboard.quickActions': 'ඉක්මන් ක්‍රියා', 'dashboard.searchReports': 'වාර්තා සොයන්න', 'dashboard.searchReportsDesc': 'නැති සහ හමු වූ භාණ්ඩ සොයන්න', 'dashboard.reportLostDesc': 'මාර්ගෝපදේශිත වාර්තාව ආරම්භ කරන්න', 'dashboard.reportFoundDesc': 'භාණ්ඩය ආරක්ෂා කර වාර්තා කරන්න', 'dashboard.reviewMatches': 'ගැළපීම් පරීක්ෂා කරන්න', 'dashboard.reviewMatchesDesc': 'පැහැදිලි කළ හැකි යෝජනා බලන්න', 'dashboard.lostReports': 'නැති වූ වාර්තා', 'dashboard.foundReports': 'හමු වූ වාර්තා', 'dashboard.submittedClaims': 'යොමු කළ හිමිකම්', 'dashboard.recoveredItems': 'නැවත ලබාදුන් භාණ්ඩ', 'dashboard.matchesDesc': 'සමානතා ලකුණු යෝජනා පමණි; සාක්ෂි නොවේ.', 'dashboard.noSuggestions': 'තවම යෝජනා නැහැ', 'dashboard.noSuggestionsDesc': 'පැහැදිලි ඡායාරූප, ස්ථාන, දින සහ විශේෂ ලකුණු ගැළපීම් වැඩිදියුණු කරයි.', 'dashboard.optionalSetup': 'අමතර සැකසුම්',
    'search.title': 'නැති සහ හමු වූ භාණ්ඩ සොයන්න',
