    'about.subtitle': 'தனியுரிமையை மதிக்கும் AI உதவியுள்ள பல்கலைக்கழக பொருள் மீட்பு சேவை.',
    'about.missionTitle': 'நோக்கம் மற்றும் வரம்பு',
    'about.missionP1': 'பல்கலைக்கழக சமூகங்களில் மாணவர் அட்டைகள், சாவிகள், பணப்பைகள், கணிப்பான்கள், தொலைபேசிகள் மற்றும் குறிப்புப் புத்தகங்கள் அடிக்கடி தொலைக்கப்படுகின்றன. கைப்பதிவுகளும் சிதறிய சமூக ஊடக பதிவுகளும் தேடலையும் சரிபார்ப்பையும் கடினமாக்குகின்றன.',
    'about.missionP2': 'Smart Lost & Found தொலைந்த பொருட்களை அறிவிக்கவும், கிடைத்த பொருட்களைப் பதிவு செய்யவும், வளாக அறிக்கைகளிலிருந்து தரவரிசைப்படுத்தப்பட்ட பரிந்துரைகளைப் பெறவும் ஒரே நேரடி தளத்தை வழங்குகிறது.',
    'about.matchingTitle': 'விளக்கக்கூடிய பொருத்தம்',
    'about.matchingDesc': 'கட்டுப்படுத்தப்பட்ட ஒற்றுமை மதிப்பெண்கள் வகை, உரை, இடம், தேதி, குறிச்சொற்கள் மற்றும் தனியுரிமை பாதுகாப்பான பட metadata-ஐ ஒப்பிடுகின்றன. மதிப்பெண் உரிமையின் சான்றல்ல.',
    'about.visionTitle': 'மதிப்பாய்வு செய்யக்கூடிய பட உதவி',
    'about.visionDesc': 'அங்கீகரிக்கப்பட்ட provider அமைக்கப்பட்டால், படங்கள் உணர்வுபூர்வமற்ற labels, நிறங்கள் மற்றும் பொருள் விவரங்களை பரிந்துரைக்கலாம். ஒவ்வொரு பரிந்துரையையும் பயனர் மதிப்பாய்வு செய்கிறார்; கையேடு மாற்று எப்போதும் உள்ளது.',
    'about.reclaimTitle': 'மனித சரிபார்ப்புடன் மீட்பு',
    'about.reclaimDesc': 'தொடர்பு பகிர்வு அல்லது ஒப்படைப்புக்கு முன் அறிக்கையாளர் மற்றும் அங்கீகரிக்கப்பட்ட நிர்வாகிகள் தனிப்பட்ட ஆதாரங்களையும் உரிமை பதில்களையும் மதிப்பாய்வு செய்கிறார்கள்.',
    'about.policyTitle': 'தரவு மற்றும் அமைப்பு கொள்கைகள்',
    'about.policyIntro': 'மீட்பு செயல்முறை முழுவதும் தனியுரிமை, ஆதார அணுகல் மற்றும் தக்கவைப்பு கட்டுப்பாடுகள் பயன்படுத்தப்படுகின்றன.',
    'about.publicPrivacyLabel': 'பொது தனியுரிமை',
    'about.publicPrivacyDesc': 'அறிக்கையாளர் வெளிப்படையாக பொது சேனலைத் தேர்ந்தெடுக்கும்வரை அல்லது அங்கீகரிக்கப்பட்ட claim நடவடிக்கை வெளியிடும்வரை தொடர்பு விவரங்கள் மறைக்கப்படும்.',
    'about.privateEvidenceLabel': 'தனிப்பட்ட ஆதாரம்',
    'about.privateEvidenceDesc': 'உரிமை ஆதாரம் அங்கீகரிக்கப்பட்ட பங்கேற்பாளர்கள் மற்றும் நிர்வாகிகளுக்கு மட்டுமே; media அணுகல் காலவரையறையுடன் உள்ளது.',
    'about.retentionLabel': 'தீர்க்கப்பட்ட அறிக்கை தக்கவைப்பு',
    'about.retentionDesc': 'தீர்க்கப்பட்ட அறிக்கைகள் நிர்வாகி அங்கீகரித்த காலத்தைப் பின்பற்றுகின்றன; அமைக்கப்பட்ட பாதுகாப்பு குறைந்தபட்சத்திற்கு முன் archive செய்யப்படாது.',
    'about.archiveNote': 'Archive செய்யப்பட்ட பொது அறிக்கைகளில் பொது விளக்கமும் media-வும் நீக்கப்படும். செயல்பாட்டு மற்றும் audit பதிவுகள் ஆவணப்படுத்தப்பட்ட தக்கவைப்பு மற்றும் பெயரில்லாக்க விதிகளைப் பின்பற்றுகின்றன.',
    'contact.title': 'ஆதரவைத் தொடர்புகொள்ளுங்கள்',
    'contact.subtitle': 'அங்கீகரிக்கப்பட்ட பல்கலைக்கழக ஆதரவு வழிகளைப் பயன்படுத்துங்கள் அல்லது உள்நுழைந்து தள கருத்தை அனுப்புங்கள்.',
    'contact.office': 'பல்கலைக்கழக அலுவலகம்',
