    'home.badge': 'பல்கலைக்கழக Smart Lost & Found அமைப்பு', 'home.title': 'SEUSL-இல் ஏதாவது தொலைந்ததா?', 'home.titleAccent': 'அதை புத்திசாலித்தனமாக மீட்கவும்.', 'home.subtitle': 'இரண்டு நிமிடங்களுக்குள் அறிவிக்கவும். தொடர்புத் தகவலை பாதுகாத்தபடி AI உதவி தொலைந்த மற்றும் கிடைத்த அறிக்கைகளை இணைக்கிறது.', 'home.reportLost': 'தொலைந்த பொருளை அறிவிக்க', 'home.reportFound': 'கிடைத்த பொருளை அறிவிக்க', 'home.searchReports': 'தற்போதைய அறிக்கைகளைத் தேடுக', 'home.completedRecoveries': 'முடிந்த மீட்புகள்', 'home.activeAccounts': 'செயலில் உள்ள கணக்குகள்', 'home.openMatches': 'திறந்த பொருத்த பரிந்துரைகள்', 'home.featuresTitle': 'Smart L&F பாதுகாப்பாக செயல்படும் விதம்', 'home.featureMatching': 'விளக்கக்கூடிய AI பொருத்தம்', 'home.featureMatchingDesc': 'பொருள் விவரங்கள், இடம், நேரம் மற்றும் தனியுரிமை பாதுகாக்கப்பட்ட பட ஆதாரங்களை ஒப்பிடுகிறது. மதிப்பெண் உரிமைச் சான்றல்ல.', 'home.featureRealtime': 'நேரடி புதுப்பிப்புகள்', 'home.featureRealtimeDesc': 'சாத்தியமான பொருத்தம் அல்லது கோரிக்கை நிலை மாறும்போது அறிவிப்புகளைப் பெறுங்கள்.', 'home.featureHuman': 'மனித சரிபார்ப்பு', 'home.featureHumanDesc': 'ஒப்படைப்பிற்கு முன் அறிக்கையாளர் மற்றும் அங்கீகரிக்கப்பட்ட நிர்வாகிகள் தனிப்பட்ட ஆதாரத்தைச் சரிபார்க்கிறார்கள்.', 'home.latestLost': 'சமீபத்திய தொலைந்த அறிக்கைகள்', 'home.latestLostDesc': 'மாணவர்கள் சமீபத்தில் தொலைந்ததாக அறிவித்த பொருட்கள்', 'home.latestFound': 'சமீபத்திய கிடைத்த பொருட்கள்', 'home.latestFoundDesc': 'வளாகத்தில் கிடைத்து பாதுகாக்கப்பட்ட பொருட்கள்', 'home.location': 'இடம்', 'home.reported': 'அறிவிக்கப்பட்டது', 'home.found': 'கிடைத்தது',
